import time, jax, jax.numpy as jnp, numpy as np
from reference import reference
def make(B, ones=True, bounds=None, prec=None):
    def candidate(q, k, v):
        seq, d = q.shape[-2], q.shape[-1]
        q = q * (1.0 / jnp.sqrt(jnp.float32(d)))
        v1 = jnp.concatenate([v, jnp.ones(v.shape[:-1] + (1,), v.dtype)], axis=-1) if ones else v
        outs = []
        bs = bounds or list(range(0, seq, B)) + [seq]
        for s, e in zip(bs[:-1], bs[1:]):
            qb = q[..., s:e, :]
            sc = jnp.einsum("bhqd,bhkd->bhqk", qb, k[..., :e, :])
            mask = jnp.arange(e)[None, :] <= jnp.arange(s, e)[:, None]
            sc = jnp.where(mask, sc, -jnp.inf)
            w = jnp.exp(sc - jnp.max(sc, axis=-1, keepdims=True))
            o = jnp.einsum("bhqk,bhkd->bhqd", w, v1[..., :e, :])
            if ones: outs.append(o[..., :d] / o[..., d:])
            else: outs.append(o / jnp.sum(w, -1, keepdims=True))
        return jnp.concatenate(outs, axis=-2)
    return candidate
key = jax.random.PRNGKey(0)
q, k, v = [jax.random.normal(kk, (2,16,2048,64), jnp.float32) for kk in jax.random.split(key, 3)]
fns = {"ref": reference}
for B in (64, 128, 256, 512, 1024):
    fns[f"B{B}"] = make(B)
    fns[f"B{B}_noones"] = make(B, ones=False)
fns["nonuni"] = make(0, bounds=[0,512,896,1152,1408,1664,1856,2048])
fns["nonuni2"] = make(0, bounds=[0,768,1152,1408,1664,1856,2048])
js = {n: jax.jit(f) for n, f in fns.items()}
r = js["ref"](q,k,v)
for n, f in js.items():
    o = f(q,k,v); o.block_until_ready()
    print(n, "maxerr", float(jnp.max(jnp.abs(o-r))))
best = {n: 1e9 for n in js}
for rnd in range(5):
    for n, f in js.items():
        t = time.perf_counter()
        for _ in range(10): o = f(q,k,v)
        o.block_until_ready()
        best[n] = min(best[n], (time.perf_counter()-t)/10*1e3)
for n, t in best.items(): print(f"{n:15s} {t:.3f} ms")
EOF
