import time, sys, jax, jax.numpy as jnp
from reference import reference
def make(B, barrier=True, split=False):
    def candidate(q, k, v):
        seq, d = q.shape[-2], q.shape[-1]
        q = q * (1.0 / jnp.sqrt(jnp.float32(d)))
        v1 = jnp.concatenate([v, jnp.ones(v.shape[:-1] + (1,), v.dtype)], axis=-1)
        ar = jnp.arange(seq)
        if barrier: ar = jax.lax.optimization_barrier(ar)
        outs = []
        for s in range(0, seq, B):
            e = min(s + B, seq)
            qb = q[..., s:e, :]
            sc = jnp.einsum("bhqd,bhkd->bhqk", qb, k[..., :e, :])
            mask = ar[None, :e] <= ar[s:e, None]
            sc = jnp.where(mask, sc, -jnp.inf)
            w = jnp.exp(sc - jnp.max(sc, axis=-1, keepdims=True))
            o = jnp.einsum("bhqk,bhkd->bhqd", w, v1[..., :e, :])
            outs.append(o[..., :d] / o[..., d:])
        return jnp.concatenate(outs, axis=-2)
    return candidate
key = jax.random.PRNGKey(0)
q, k, v = [jax.random.normal(kk, (2,16,2048,64), jnp.float32) for kk in jax.random.split(key, 3)]
fns = {"ref": reference}
for a in sys.argv[1:]:
    B, bar = a.split(","); fns[a] = make(int(B), bar == "1")
js = {n: jax.jit(f) for n, f in fns.items()}
r = js["ref"](q,k,v)
for n, f in js.items():
    t=time.perf_counter(); o = f(q,k,v); o.block_until_ready()
    print(n, "compile", round(time.perf_counter()-t,1), "maxerr", float(jnp.max(jnp.abs(o-r))), flush=True)
best = {n: 1e9 for n in js}
for rnd in range(5):
    for n, f in js.items():
        t = time.perf_counter()
        for _ in range(10): o = f(q,k,v)
        o.block_until_ready()
        best[n] = min(best[n], (time.perf_counter()-t)/10*1e3)
for n, t in best.items(): print(f"{n:15s} {t:.3f} ms")
